('g6_1_sci_u1_review_d#20','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C17',3,'error','auto','욕실 청소를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X27']::text[],false,'{"seq":20,"concept":"SC6-1-u1-C17","difficulty":3,"kind":"error","stem":"욕실 청소를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하진 — 「욕실의 때와 세균은 산성 표백제로 없애.」","correct":true,"mis_target":"SC6-1-u1-X27"},{"t":"우림 — 「욕실 청소용 표백제는 염기성이야.」","mis":"SC6-1-u1-X27"},{"t":"서율 — 「표백제는 단백질을 녹여 때를 없애.」","mis":"SC6-1-u1-X27"}],"explanation":["표백제의 성질이에요.","염기성이에요.","하진이 잘못 말했어요."]}'::jsonb),
('g6_1_sci_u1_review_d#21','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C20',3,'error','auto','흙의 산성화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X32','SC6-1-u1-X37']::text[],false,'{"seq":21,"concept":"SC6-1-u1-C20","difficulty":3,"kind":"error","stem":"흙의 산성화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「흙이 산성을 띠면 식물이 더 잘 자라.」","correct":true,"mis_target":"SC6-1-u1-X32"},{"t":"은비 — 「흙이 산성을 띠면 미생물 활동이 줄어.」","mis":"SC6-1-u1-X32"},{"t":"라임 — 「화학 비료를 지나치게 쓰면 흙이 산성을 띨 수 있어.」","mis":"SC6-1-u1-X37"}],"explanation":["토양 산성화의 피해예요.","식물 생장이 억제돼요.","민호가 잘못 말했어요."]}'::jsonb),
('g6_1_sci_u1_review_d#22','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C8',3,'error','auto','붉은 양배추 용액을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u1-X14','SC6-1-u1-X13']::text[],false,'{"seq":22,"concept":"SC6-1-u1-C8","difficulty":3,"kind":"error","stem":"붉은 양배추 용액을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「양배추 용액이 연한 붉은색이면 산성이 아니야.」","correct":true,"mis_target":"SC6-1-u1-X14"},{"t":"초아 — 「붉은색 계열이면 산성이야.」","mis":"SC6-1-u1-X13"},{"t":"윤재 — 「푸른색이나 노란색 계열이면 염기성이야.」","mis":"SC6-1-u1-X13"}],"explanation":["연해도 계열은 같아요.","붉은색 계열이에요.","태민이 잘못 말했어요."]}'::jsonb),
('g6_1_sci_u1_review_d#23','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C21',4,'mc','auto','나래반 일지 ⑦과 ⑧을 함께 볼 때 가장 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u1-X35','SC6-1-u1-X36','SC6-1-u1-X39']::text[],false,'{"seq":23,"concept":"SC6-1-u1-C21","difficulty":4,"kind":"mc","stem":"나래반 일지 ⑦과 ⑧을 함께 볼 때 가장 알맞은 것은 어느 것인가요?","options":[{"t":"산성화는 조개껍데기·조각상 등에 피해를 주므로 원인을 줄이고, 출처를 밝혀 피해를 알리는 노력을 함께 해야 한다","correct":true},{"t":"산성화는 먼 곳의 일이라 알릴 필요가 없다","mis":"SC6-1-u1-X35"},{"t":"산성화는 저절로 사라지므로 기다리면 된다","mis":"SC6-1-u1-X36"},{"t":"출처 없이 빠르게 퍼뜨리는 것이 가장 중요하다","mis":"SC6-1-u1-X39"}],"explanation":["⑦은 피해와 약속이에요.","⑧은 알리기예요.","둘을 함께 해요."],"asset":{"type":"passage","lines":["주제 — 토양 산성화","조사 — 원인·현황·전망·대책을 모둠원이 나누어 맡음","자료 — 누리집 사진을 쓸 때 출처와 주소를 함께 적음","공유 — 학급 누리집에 올리고 다른 모둠의 잘한 점을 댓글로 씀"],"title":"나래반 일지 ⑧ 알림 동영상 계획"}}'::jsonb),
('g6_1_sci_u1_review_d#24','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C18',4,'essay','teacher','나래반 일지 ⑤의 네 가지 예를 산성 용액을 이용한 것과 염기성 용액을 이용한 것으로 나누고, 그중 두 가지를 골라 없애려는 물질의 성질과 함께 왜 그 용액을 쓰는지 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC6-1-u1-C18","difficulty":4,"kind":"essay","stem":"나래반 일지 ⑤의 네 가지 예를 산성 용액을 이용한 것과 염기성 용액을 이용한 것으로 나누고, 그중 두 가지를 골라 없애려는 물질의 성질과 함께 왜 그 용액을 쓰는지 설명하세요.","answer_guide":{"answer":"예: 산성 용액을 이용한 것은 할머니의 식초, 아빠의 변기 청소용 세제이고, 염기성 용액을 이용한 것은 삼촌의 제산제, 엄마의 하수구 세정제이다. 도마의 비린내는 염기성 물질이라 산성인 식초로 닦으면 성질이 약해져 냄새가 줄어든다. 위액은 산성이라 염기성인 제산제를 먹으면 산성이 약해져 속 쓰림이 줄어든다. 이처럼 없애려는 물질과 반대되는 성질의 용액을 이용한다.","scoring_points":["네 가지를 바르게 나누었는가","두 가지 예에서 없애려는 물질의 성질을 썼는가","반대 성질의 용액을 쓰는 까닭을 설명했는가"]},"explanation":["둘로 나눠요.","두 가지를 골라요.","반대 성질로 설명해요."],"asset":{"type":"passage","lines":["할머니 — 생선을 손질한 도마를 식초로 닦으신다.","삼촌 — 속이 쓰릴 때 제산제를 드신다.","엄마 — 머리카락으로 막힌 하수구를 하수구 세정제로 뚫으신다.","아빠 — 변기 청소용 세제로 변기를 청소하신다."],"title":"나래반 일지 ⑤ 우리 집 산과 염기"}}'::jsonb),
('g6_1_sci_u1_review_d#25','sci',6,1,'u1','','g6_1_sci_u1_review_d','unit_review','SC6-1-u1-C21',4,'essay','teacher','「산과 염기」에서 배운 것을 바탕으로 우리 반 「산성화 줄이기 약속」 세 가지를 만들고, 각 약속이 어떤 과학적 사실과 이어지는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC6-1-u1-C21","difficulty":4,"kind":"essay","stem":"「산과 염기」에서 배운 것을 바탕으로 우리 반 「산성화 줄이기 약속」 세 가지를 만들고, 각 약속이 어떤 과학적 사실과 이어지는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 가까운 곳은 걷거나 자전거를 탄다 — 자동차 배기가스 같은 대기 오염 물질이 빗물에 녹으면 산성비가 되기 때문이다. 둘째, 먼 곳은 대중교통을 이용한다 — 이산화 탄소가 줄면 해양 산성화로 조개껍데기가 얇아지는 피해를 줄일 수 있기 때문이다. 셋째, 산성화 피해를 출처와 함께 친구들에게 알린다 — 산성화는 전 세계적인 문제라 여러 사람이 함께 노력해야 하기 때문이다.","scoring_points":["약속 세 가지를 썼는가","각 약속을 산성비·해양 산성화 등 과학적 사실과 이었는가","우리가 실천할 수 있는 약속인가"]},"explanation":["약속을 셋 정해요.","과학적 사실과 이어요.","실천할 수 있게 써요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SC6-1-u2-C1','sci',6,1,'u2',1,'나무토막 옮기기 — 색 테이프로 출발선과 결승선을 표시 → 모둠원끼리 옮기는 방법(머리에 얹고·어깨에 얹고·무릎에 끼고·발등에 얹고)을 정함 → 걸어서 옮김 → 떨어뜨리면 출발선으로 돌아와 다시 시작 → 먼저·나중에 통과한 친구 이야기 · 뛰지 않기, 떨어뜨린 나무토막은 바로 줍기, 던지며 장난치지 않기, 통과한 뒤 손으로 잡아 내려놓기 · 겨루기보다 걷는 모습 살펴보기',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],1),
('SC6-1-u2-C2','sci',6,1,'u2',1,'걷는 빠르기 — 같은 곳까지 걸어도 사람마다 걷는 빠르기가 다름 · 빠르게 걷는 친구도 느리게 걷는 친구도 있음 · 결승선을 가장 먼저 통과한 친구가 가장 빠르게 걸은 친구 · 머리에 얹고 걸은 친구가 가장 먼저, 발등에 얹고 걸은 친구가 가장 나중에 통과(한 걸음씩 조심조심) · 빠르기를 비교하는 방법은 다음 시간부터 알아봄',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],2),
('SC6-1-u2-C3','sci',6,1,'u2',2,'운동 — 시간이 지남에 따라 물체의 위치가 변할 때 물체가 운동한다고 함 · 과학에서 운동을 나타낼 때는 사람이나 동물도 물체에 포함됨 · 운동하는 물체: 굴러가는 공, 날아가는 갈매기, 바다 위를 나아가는 배 등',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],3),
('SC6-1-u2-C4','sci',6,1,'u2',2,'일상의 운동과 과학의 운동 — 신체의 운동(몸을 단련하거나 건강을 위해 움직이는 일), 사회적 운동(물 절약 운동처럼 목적을 이루려고 힘쓰는 일), 운동 경기(규칙과 방법에 따라 기량을 겨루는 일)와 과학에서의 운동(시간이 지남에 따라 물체의 위치가 변하는 것)은 뜻이 다름 · 철봉에 가만히 매달려 있는 것은 위치가 변하지 않으므로 과학에서의 운동이 아님',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],4),
('SC6-1-u2-C5','sci',6,1,'u2',2,'두 사진 비교 — 삼각대에 스마트 기기를 고정하고(쓰러지지 않는지 확인) 5초 간격으로 사진을 두 번 찍음(타이머 기능) · 5초 뒤 같은 위치에 있는 물체(책상·창문·화분·창밖을 보는 친구·책 읽는 친구)와 다른 위치에 있는 물체(걸어가는 친구·시곗바늘) · 공원의 처음 모습과 얼마 뒤 모습에서 운동하는 물체(자전거 타는 사람·오리 배·비행기·달리는 사람) · 운동하는 물체와 부딪히지 않기, 창밖으로 고개·손 내밀지 않기, 다른 사람을 찍은 사진은 온라인에 올리지 않고 관찰이 끝나면 삭제',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],5),
('SC6-1-u2-C6','sci',6,1,'u2',2,'같은 물체도 운동할 때와 하지 않을 때가 있음 — 달리는 자동차는 운동하고 주차된 자동차는 운동하지 않음 · 운동하는 물체와 운동하지 않는 물체가 정해져 있는 것이 아님 · 물체의 모습이 아니라 시간이 지남에 따라 위치가 변했는지에 초점을 둠',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],6),
('SC6-1-u2-C7','sci',6,1,'u2',3,'운동의 표현 — 물체의 운동은 물체가 이동하는 데 걸린 시간과 물체의 위치 변화로 표현 · 위치 변화는 처음 위치(운동을 시작하는 곳)와 나중 위치(얼마 뒤 물체가 있는 곳)로 나타냄 · 걸린 시간·처음 위치·나중 위치를 모두 넣어 말함(예: 승강기가 15초 동안 1층에서 5층으로 이동했다, 기차가 1시간 동안 출발역에서 도착역으로 이동했다)',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],7),
('SC6-1-u2-C8','sci',6,1,'u2',3,'칸 모양 좌표평면 — 가로선과 세로선이 직각으로 만나는 평면으로 물체의 위치를 나타내는 데 도움을 줌 · 정원판에서 분수로부터 꽃이 있는 방향과 칸 수로 위치를 말함(수선화꽃: 왼쪽 3칸, 제비꽃: 위쪽 2칸, 유채꽃: 오른쪽 2칸·위쪽 3칸, 진달래꽃: 오른쪽 1칸·아래쪽 1칸) · 두 방향이 필요하면 두 방향을 모두 말함',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],8),
('SC6-1-u2-C9','sci',6,1,'u2',3,'꿀벌 놀이 — 꿀벌은 오른쪽·왼쪽·위쪽·아래쪽으로 한 칸씩 이동하고 한 칸에 1초 · 진달래꽃에서 유채꽃까지 5칸이면 「꿀벌은 5초 동안 진달래꽃에서 유채꽃으로 이동했다」 · 제비꽃→유채꽃 3초, 제비꽃→진달래꽃 4초 · 꽃 붙임딱지는 정해진 곳 이외에 얼굴이나 몸에 붙이지 않기',ARRAY['일상생활에서 물체의 운동을 관찰하여 운동하는 물체의 특징을 찾고, 물체의 운동을 걸린 시간과 위치 변화로 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],9),
('SC6-1-u2-C10','sci',6,1,'u2',4,'같은 시간 동안의 빠르기 비교 — 이동한 거리를 측정해 비교 · 같은 시간 동안 긴 거리를 이동한 물체가 더 빠름 · 5초 동안 빨간색 자동차 135 cm, 파란색 자동차 122 cm → 빨간색이 더 빠름 · 동시에 땅을 파기 시작해 동시에 나온 두더지와 개미는 더 길게 판 두더지가 더 빠름 · 「무궁화꽃이 피었습니다」 놀이는 같은 시간 동안 가장 긴 거리를 이동해야 먼저 도착',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],10),
('SC6-1-u2-C11','sci',6,1,'u2',4,'같은 시간 실험 — 색 테이프로 출발선, 줄자를 출발선과 수직으로 펼쳐 경주로(줄자는 가운데) · 경주로 전체가 보이게 스마트 기기를 삼각대에 고정 · 신호에 따라 태엽 자동차 두 대를 동시에 출발시키고 5초 뒤 사진 · 사진으로 이동 거리 확인(반올림하여 일의 자리까지) · 모둠원과 역할을 나누어 협력 · 줄자에 손 다치지 않게, 태엽을 과도하게 감지 않게',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],11),
('SC6-1-u2-C12','sci',6,1,'u2',4,'맨 앞의 물체 — 출발선이 다르거나 동시에 출발하지 않았다면 지금 맨 앞에 있는 물체가 가장 빠르다고 할 수 없음 · 그래서 같은 시간 동안의 빠르기를 비교할 때는 같은 출발선에서 동시에 출발시킴 · 앞서 출발한 오토바이, 다른 출발선의 자동차는 위치만으로 비교할 수 없음',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],12),
('SC6-1-u2-C13','sci',6,1,'u2',4,'1초 동안 이동할 수 있는 거리 — 공식 경기 기록과 세계 기록을 바탕으로 나타낸 값: 거북 약 0.3 m, 사람 약 10 m, 루지 약 39 m, 송골매 약 108 m, 드론 약 133 m · 기록을 바탕으로 한 값이지 언제나 그 빠르기로 움직인다는 뜻이 아님 · 같은 시간(1초) 동안 이동할 수 있는 거리가 길수록 빠름',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],13),
('SC6-1-u2-C14','sci',6,1,'u2',5,'같은 거리의 빠르기 비교 — 걸린 시간을 측정해 비교 · 같은 거리를 이동하는 데 걸린 시간이 짧은 물체가 더 빠름 · 100 cm를 초록색 자동차 4.2초, 노란색 자동차 5.8초 → 초록색이 더 빠름 · 수영·달리기 경기는 결승선까지 걸린 시간이 짧은 순서대로 순위를 정함(50 m를 8초에 간 친구가 1위)',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],14),
('SC6-1-u2-C15','sci',6,1,'u2',5,'같은 거리 실험 — 출발선에서 수직으로 100 cm 떨어진 곳에 결승선 표시(줄자는 결승선 표시할 때만 쓰고 잘 말아 보관) · 자동차의 앞부분이 출발선에 오게 놓음 · 정확한 시간 측정과 편리한 초시계 사용을 위해 한 대씩 출발 · 초시계를 든 친구의 신호에 출발, 앞부분이 결승선에 닿은 시간을 반올림하여 소수 첫째 자리까지 · 역할을 나누어 협력',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],15),
('SC6-1-u2-C16','sci',6,1,'u2',5,'같은 거리를 이동하는 데 걸린 시간을 재는 종목 — 달리기(트랙을 달리는 데 걸린 시간), 조정(보트를 타고 노를 저어 결승선까지, 뒤로 나아감), 쇼트트랙(얼음 트랙을 돎), 알파인 스키(눈 덮인 슬로프를 내려감), 봅슬레이(썰매를 타고 얼음 트랙을 내려감, 0.01초 차이로 순위가 정해지기도) · 모두 걸린 시간이 짧은 순서대로 순위를 정함',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],16),
('SC6-1-u2-C17','sci',6,1,'u2',6,'속력 — 일정한 시간 동안 물체가 이동한 거리 · 속력 = 이동 거리 ÷ 걸린 시간 · 이동 거리와 걸린 시간이 모두 다른 물체의 빠르기는 속력을 구해 비교 · 속력은 숫자와 단위를 함께 씀 · 빨간색 자동차 135 cm ÷ 5 s = 27.0 cm/s, 파란색 122 cm ÷ 5 s = 24.4 cm/s',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],17),
('SC6-1-u2-C18','sci',6,1,'u2',6,'속력의 단위와 읽기 — km/h(킬로미터 매 시), m/s(미터 매 초), cm/s(센티미터 매 초) · 「매」는 「하나하나마다」라는 뜻 · 60 km/h는 「육십 킬로미터 매 시」로 읽고 1시간 동안 60 km를 이동한 것과 같은 빠르기 · 2 m/s는 1초 동안 2 m를 이동한 것과 같은 빠르기',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],18),
('SC6-1-u2-C19','sci',6,1,'u2',6,'속력으로 비교 — 속력의 단위가 같을 때 속력을 나타내는 숫자가 클수록 더 빠름 · 단위가 다르면(10 km/h와 5 m/s) 숫자만으로 바로 비교할 수 없음 · 자전거 20 km/h, 자동차 72.5 km/h, 기차 150 km/h, 배 34.5 km/h, 비행기 900 km/h → 비행기·기차·자동차·배·자전거 순 · 치타 50 m를 10초(5 m/s), 호랑이 100 m를 25초(4 m/s) → 치타가 더 빠름',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],19),
('SC6-1-u2-C20','sci',6,1,'u2',6,'속력이 뜻하는 것 — 27.0 cm/s는 매 초 똑같이 27.0 cm씩 이동했다는 뜻이 아니라 전체 이동 거리와 전체 걸린 시간으로 구한 값 · 빠르기를 속력으로 나타내면 숫자와 단위로 정확히 전할 수 있어 의사소통하기에 편리함',ARRAY['같은 시간 동안 이동한 거리 또는 같은 거리를 이동하는 데 걸린 시간을 측정하여 물체의 빠르기를 비교하고, 속력을 구해 빠르기를 표현(문구 초안 — 성취기준 코드 W7 확인)']::text[],20),
('SC6-1-u2-C21','sci',6,1,'u2',7,'속력과 위험 — 속력은 먼 곳까지 빠르게 갈 수 있어 편리하지만 속력이 빠른 물체는 바로 멈추기 어려워 안전사고 위험이 커짐 · 제동 거리: 운전자가 브레이크를 밟은 뒤 자동차가 완전히 멈출 때까지 움직인 거리 · 같은 도로에서 속력이 빠를수록 제동 거리가 길어지고(30 km/h 1.5 m → 60 km/h 10.1 m, 마른 노면) 빙판길처럼 미끄러운 도로에서는 더 길어짐(30 km/h 10.7 m) · 지그재그 차선은 도로 폭을 좁게 느껴 속력을 줄이도록 유도',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],21),
('SC6-1-u2-C22','sci',6,1,'u2',7,'안전 수칙 — 계단은 뛰지 않고 걸어서 · 자동계단은 뛰거나 걷지 않고 손잡이를 잡고 서서 · 자전거는 보호 장비를 착용하고 적당한 속력으로 · 운전자는 어린이 보호 구역에서 정해진 속력보다 천천히 · 횡단보도는 좌우를 살피며 건너고 자전거·킥보드에서 내려서 건넘 · 길을 걸을 때 스마트 기기를 보지 않고 주위를 살핌 · 비나 눈이 오는 날 더 주의 · 교통안전 수칙은 어린이인 나부터 실천',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],22),
('SC6-1-u2-C23','sci',6,1,'u2',7,'안전장치 — 자동차: 안전띠(충돌하거나 갑자기 멈출 때 탑승자를 좌석에 고정), 에어백(빠른 속력으로 충돌할 때 공기주머니를 부풀려 탑승자 보호), 차간 거리 유지 장치(앞차가 갑자기 정지했을 때를 대비해 속력을 조절하고 안전거리 유지) · 도로: 과속 방지턱(운전자가 속력을 줄이도록 유도), 안전 울타리(충돌 때 충격을 흡수하고 보행자 보호), 과속 경보 시스템(자동차의 속력을 실시간으로 측정해 알려 줌) · 안전장치가 있어도 안전 수칙을 함께 지켜야 함',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],23),
('SC6-1-u2-C24','sci',6,1,'u2',7,'조사·공유 — 검색어(보행자 안전 수칙, 운전자 안전 수칙, 자전거 안전 수칙, 어린이 보호 구역, 자동차 안전장치, 도로 안전장치)로 조사 · 믿을 만한 자료인지 확인하고 출처를 밝힘 · 비슷한 내용끼리 묶어 공유 플랫폼에 올림 · 나와 다른 사람의 개인 정보를 누리망에 함부로 올리지 않고 바르고 고운 말로 댓글 · 다른 모둠의 내용을 읽고 새로 알게 된 점을 댓글로',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],24),
('SC6-1-u2-C25','sci',6,1,'u2',8,'실천 점검표 — 안전 수칙은 한 번 안다고 지켜지지 않아 매일 실천하고 점검해야 함 · 모둠원의 의견을 종합해 넣을 수칙을 정하고 만드는 방법은 너무 복잡하거나 어렵지 않게 계획 · 도화지·가위·풀·그림 도구로 병풍 책(앞 칸 수칙, 뒤 칸 일주일 점검표)·화분·수첩 모양 · 잘 보이는 곳에 두고 실천한 것만 양심적으로 표시 · 표시가 많은 것보다 꾸준히 실천해 습관이 되는 것이 중요 · 활동이 끝난 뒤에도 실천',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],25),
('SC6-1-u2-C26','sci',6,1,'u2',8,'실천 결과 나누기 — 일주일 동안 실천한 결과와 느낀 점을 발표 · 바른 자세로 경청하고 친구가 실천하려고 노력한 점을 찾아 칭찬 · 잘 지키지 못한 점은 탓하지 않고 다음 주에 더 노력할 점으로 정함',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],26),
('SC6-1-u2-C27','sci',6,1,'u2',8,'스포츠 첨단 기술 — 움직임 센서(선수의 등에 부착, 위치와 속력을 실시간으로 측정, 장거리 경기에서 앞서는 선수 비교), 초고속 카메라(결승선, 1초에 수천 장의 사진으로 먼저 도착한 선수를 보여 줌, 사람의 눈으로 판단하기 어려울 때 공정한 판정), 3D 선수 추적 기술(경기장 주변 여러 대의 카메라, 선수의 움직임을 삼차원으로 보여 줌, 선수는 더 빠른 기록을 낼 방법을 찾고 관객은 경기에 몰입) · 첨단 기술은 공정한 경기와 기량 향상을 돕는 것이지 연습을 대신하지 않음 · 경기의 문제를 해결하려고 새 기술을 떠올리는 마음',ARRAY['속력과 관련된 안전 수칙과 안전장치를 조사·공유하고 교통안전을 생활 속에서 실천(문구 초안 — 성취기준 코드 W7 확인)']::text[],27)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SC6-1-u2-X01','sci',6,'u2',ARRAY['SC6-1-u2-C1']::text[],'나무토막 옮기기의 규칙을 잘못 안다(떨어뜨린 자리에서 이어 가기, 뛰어서 옮기기, 던지며 장난치기, 떨어진 나무토막을 그대로 두기 등)','떨어뜨리면 출발선으로 · 뛰지 않기'),
('SC6-1-u2-X02','sci',6,'u2',ARRAY['SC6-1-u2-C1','SC6-1-u2-C2']::text[],'빠르기를 살펴보는 활동을 누가 이기는지 겨루는 일로만 여긴다','겨루기보다 살펴보기'),
('SC6-1-u2-X03','sci',6,'u2',ARRAY['SC6-1-u2-C2']::text[],'모든 사람이 같은 빠르기로 걷는다고 여기거나, 옮기는 방법이 달라도 걷는 모습은 같다고 여긴다','사람마다 빠르기가 달라요'),
('SC6-1-u2-X04','sci',6,'u2',ARRAY['SC6-1-u2-C2']::text[],'결승선을 가장 나중에 통과한 친구가 가장 빠르게 걸었다고 거꾸로 판단한다','먼저 통과할수록 빨라요'),
('SC6-1-u2-X05','sci',6,'u2',ARRAY['SC6-1-u2-C3','SC6-1-u2-C7']::text[],'운동이나 운동의 표현을 무게·색깔·크기 같은 다른 성질의 변화로 여긴다','시간에 따른 위치 변화'),
('SC6-1-u2-X06','sci',6,'u2',ARRAY['SC6-1-u2-C4']::text[],'일상에서 쓰는 「운동」의 뜻과 과학에서의 운동을 섞어, 철봉에 가만히 매달리기나 물 절약 운동도 과학에서의 운동이라고 여긴다','과학에서는 위치가 변해야 해요'),
('SC6-1-u2-X07','sci',6,'u2',ARRAY['SC6-1-u2-C3']::text[],'사람이나 동물은 물체가 아니라서 운동하는 물체에 넣지 않는다고 여긴다','사람·동물도 물체에 포함'),
('SC6-1-u2-X08','sci',6,'u2',ARRAY['SC6-1-u2-C5']::text[],'두 장면을 비교할 때 같은 위치에 있는 물체와 다른 위치에 있는 물체를 바꾸어 가르거나, 운동하는 물체를 잘못 찾는다','처음과 얼마 뒤의 위치를 견줘요'),
('SC6-1-u2-X09','sci',6,'u2',ARRAY['SC6-1-u2-C6']::text[],'운동하는 물체와 운동하지 않는 물체가 정해져 있다고 여긴다(자동차는 언제나 운동한다, 주차된 자동차도 운동한다 등)','같은 물체도 경우에 따라 달라요'),
('SC6-1-u2-X10','sci',6,'u2',ARRAY['SC6-1-u2-C5']::text[],'관찰할 때의 안전과 개인 정보 보호를 잘못 안다(창밖으로 몸을 내밀기, 다른 사람 사진을 누리망에 올리기, 사진을 지우지 않기 등)','올리지 않고 삭제해요'),
('SC6-1-u2-X11','sci',6,'u2',ARRAY['SC6-1-u2-C6']::text[],'위치가 아니라 물체의 모습·자세·모양이 바뀌었는지로 운동을 판단한다','모습이 아니라 위치'),
('SC6-1-u2-X12','sci',6,'u2',ARRAY['SC6-1-u2-C7']::text[],'물체의 운동을 표현할 때 걸린 시간·처음 위치·나중 위치 가운데 하나라도 빠뜨려도 된다고 여긴다','세 가지를 모두 넣어요'),
('SC6-1-u2-X13','sci',6,'u2',ARRAY['SC6-1-u2-C7','SC6-1-u2-C9']::text[],'처음 위치와 나중 위치를 바꾸어 말한다','시작한 곳이 처음 위치'),
('SC6-1-u2-X14','sci',6,'u2',ARRAY['SC6-1-u2-C8']::text[],'칸 모양 좌표평면에서 방향이나 칸 수를 잘못 읽거나, 두 방향이 필요한 위치를 한 방향으로만 말한다','기준에서 방향과 칸 수'),
('SC6-1-u2-X15','sci',6,'u2',ARRAY['SC6-1-u2-C9']::text[],'꿀벌이 이동한 칸 수(걸린 시간)를 잘못 세거나, 대각선으로 한 번에 갈 수 있다고 여긴다','상하좌우 한 칸에 1초'),
('SC6-1-u2-X16','sci',6,'u2',ARRAY['SC6-1-u2-C7']::text[],'물체의 위치 변화를 「중간 위치」와 나중 위치로 나타낸다고 여긴다','처음 위치와 나중 위치'),
('SC6-1-u2-X17','sci',6,'u2',ARRAY['SC6-1-u2-C10']::text[],'같은 시간 동안 이동한 물체는 이동 거리가 짧을수록 더 빠르다고 여긴다','같은 시간이면 길게 간 쪽'),
('SC6-1-u2-X18','sci',6,'u2',ARRAY['SC6-1-u2-C11']::text[],'같은 시간 동안의 빠르기를 비교하는 실험 방법을 잘못 안다(따로 출발시키기, 사진 찍는 시각을 다르게 하기, 줄자를 비스듬히 펼치기 등)','같은 출발선 · 동시에 출발 · 5초 뒤'),
('SC6-1-u2-X19','sci',6,'u2',ARRAY['SC6-1-u2-C12']::text[],'출발선이나 출발 시각과 관계없이 지금 맨 앞에 있는 물체가 언제나 가장 빠르다고 여긴다','출발선과 출발 시각을 확인해요'),
('SC6-1-u2-X20','sci',6,'u2',ARRAY['SC6-1-u2-C10','SC6-1-u2-C14']::text[],'무게·색깔·태엽을 감은 정도처럼 측정하지 않은 것으로 빠르기를 판단한다','거리나 시간을 재어 비교'),
('SC6-1-u2-X21','sci',6,'u2',ARRAY['SC6-1-u2-C13']::text[],'1초 동안 이동할 수 있는 거리 자료를 언제나 그 빠르기로 움직인다는 뜻으로 여기거나, 대상과 값을 잘못 짝짓는다','기록을 바탕으로 한 값'),
('SC6-1-u2-X22','sci',6,'u2',ARRAY['SC6-1-u2-C14']::text[],'같은 거리를 이동한 물체는 걸린 시간이 길수록 더 빠르다고 여긴다','같은 거리면 빨리 닿은 쪽'),
('SC6-1-u2-X23','sci',6,'u2',ARRAY['SC6-1-u2-C15']::text[],'같은 거리를 이동하는 데 걸린 시간을 재는 실험 방법을 잘못 안다(한꺼번에 출발시키기, 줄자를 펼쳐 둔 채 출발시키기, 뒷부분을 출발선에 맞추기 등)','한 대씩 · 앞부분 · 소수 첫째 자리'),
('SC6-1-u2-X24','sci',6,'u2',ARRAY['SC6-1-u2-C14','SC6-1-u2-C16']::text[],'이동한 거리가 다른데도 걸린 시간만으로 빠르기를 비교하거나, 걸린 시간을 재지 않고 지금 앞서 있는 선수로 순위를 정한다','거리가 같을 때 시간으로'),
('SC6-1-u2-X25','sci',6,'u2',ARRAY['SC6-1-u2-C16']::text[],'걸린 시간을 재는 운동 종목과 그 설명을 잘못 짝짓는다','트랙·보트·얼음·슬로프·썰매'),
('SC6-1-u2-X26','sci',6,'u2',ARRAY['SC6-1-u2-C17']::text[],'속력을 걸린 시간을 이동 거리로 나누거나, 이동 거리에 걸린 시간을 곱해 구한다고 여긴다','이동 거리 ÷ 걸린 시간'),
('SC6-1-u2-X27','sci',6,'u2',ARRAY['SC6-1-u2-C17']::text[],'속력을 숫자만 쓰고 단위를 빠뜨리거나, 이동 거리 자체를 속력으로 여긴다','숫자와 단위를 함께'),
('SC6-1-u2-X28','sci',6,'u2',ARRAY['SC6-1-u2-C18']::text[],'속력의 단위를 잘못 읽거나 뜻을 잘못 안다(매 시와 매 초를 바꾸기, 60 km/h를 1초 동안 60 km로 여기기 등)','km/h는 1시간마다'),
('SC6-1-u2-X29','sci',6,'u2',ARRAY['SC6-1-u2-C19']::text[],'속력을 나타내는 숫자가 크면 단위와 관계없이 언제나 더 빠르다고 여긴다','단위가 같을 때만 숫자로'),
('SC6-1-u2-X30','sci',6,'u2',ARRAY['SC6-1-u2-C20']::text[],'27.0 cm/s 같은 속력을 매 초 똑같이 그만큼씩 이동했다는 뜻으로 여긴다','전체 거리와 전체 시간으로 구한 값'),
('SC6-1-u2-X31','sci',6,'u2',ARRAY['SC6-1-u2-C19']::text[],'이동 거리와 걸린 시간이 모두 다를 때, 더 먼 거리를 갔거나 더 오래 달린 쪽이 더 빠르다고 여긴다','속력을 구해 비교해요'),
('SC6-1-u2-X32','sci',6,'u2',ARRAY['SC6-1-u2-C21']::text[],'속력은 빠를수록 좋기만 하다고 여기거나, 반대로 속력은 위험만 만든다고 여긴다','편리함과 위험이 함께 있어요'),
('SC6-1-u2-X33','sci',6,'u2',ARRAY['SC6-1-u2-C21']::text[],'브레이크를 밟으면 바로 멈춘다고 여기거나, 제동 거리가 속력·도로 상태와 관계없다고 여긴다','빠를수록·미끄러울수록 길어요'),
('SC6-1-u2-X34','sci',6,'u2',ARRAY['SC6-1-u2-C22']::text[],'속력과 관련된 안전 수칙을 잘못 안다(자동계단에서 뛰기, 스마트 기기를 보며 건너기, 킥보드를 탄 채 횡단보도 건너기 등)','상황마다 지킬 수칙'),
('SC6-1-u2-X35','sci',6,'u2',ARRAY['SC6-1-u2-C22','SC6-1-u2-C25']::text[],'교통안전 수칙은 어른들만 신경 쓰면 되고 어린이와는 관계없다고 여긴다','나부터 실천해요'),
('SC6-1-u2-X36','sci',6,'u2',ARRAY['SC6-1-u2-C23']::text[],'안전장치가 설치된 곳(자동차·도로)이나 하는 일을 바꾸어 안다','안전띠·에어백은 자동차, 방지턱은 도로'),
('SC6-1-u2-X37','sci',6,'u2',ARRAY['SC6-1-u2-C23','SC6-1-u2-C22']::text[],'안전장치가 있으면 속력이 빨라도 안전하므로 안전 수칙은 지키지 않아도 된다고 여긴다','장치와 수칙을 함께'),
('SC6-1-u2-X38','sci',6,'u2',ARRAY['SC6-1-u2-C24']::text[],'조사한 자료를 쓰고 나누는 태도를 잘못 안다(출처 없이 쓰기, 믿을 만한지 확인하지 않기, 개인 정보 올리기, 거친 댓글 등)','출처 · 확인 · 고운 말'),
('SC6-1-u2-X39','sci',6,'u2',ARRAY['SC6-1-u2-C25']::text[],'표시가 많은 점검표일수록 좋은 점검표라고 여겨, 실천하지 못한 날도 칸을 채운다','양심적으로 표시해요'),
('SC6-1-u2-X40','sci',6,'u2',ARRAY['SC6-1-u2-C25']::text[],'실천 점검표를 만드는 방법을 잘못 안다(혼자 정하기, 너무 복잡하게 계획하기, 보이지 않는 곳에 두기, 일주일 뒤 실천을 그만두기 등)','함께 정하고 쉽게, 꾸준히'),
('SC6-1-u2-X41','sci',6,'u2',ARRAY['SC6-1-u2-C26']::text[],'실천 결과를 나눌 때 잘 지키지 못한 친구를 탓하거나 친구의 발표를 듣지 않는다','노력한 점을 칭찬해요'),
('SC6-1-u2-X42','sci',6,'u2',ARRAY['SC6-1-u2-C27']::text[],'스포츠 첨단 기술이 하는 일이나 놓이는 곳을 서로 바꾸어 안다','센서 · 초고속 카메라 · 3D 추적'),
('SC6-1-u2-X43','sci',6,'u2',ARRAY['SC6-1-u2-C27']::text[],'첨단 기술이 있으니 선수는 연습하지 않아도 된다고 여기거나, 첨단 기술은 재미만을 위한 것이라고 여긴다','공정한 판정과 기량 향상을 도와요')
