('g6_1_sci_u2_L01_basic#2','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',1,'mc','auto','나무토막을 옮기다 떨어뜨리면 어떻게 하나요?',ARRAY['SC6-1-u2-X01']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C1","difficulty":1,"kind":"mc","stem":"나무토막을 옮기다 떨어뜨리면 어떻게 하나요?","options":[{"t":"출발선으로 돌아와서 다시 시작한다","correct":true},{"t":"떨어진 자리에서 그대로 이어서 걷는다","mis":"SC6-1-u2-X01"},{"t":"친구에게 대신 옮겨 달라고 한다","mis":"SC6-1-u2-X01"},{"t":"그냥 두고 결승선까지 뛰어간다","mis":"SC6-1-u2-X01"}],"explanation":["놀이 규칙이에요.","처음부터 다시 해요.","출발선으로 돌아와요."]}'::jsonb),
('g6_1_sci_u2_L01_basic#3','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',1,'ox','auto','나무토막을 옮길 때는 뛰지 않고 걸어서 옮겨요.',ARRAY['SC6-1-u2-X01']::text[],false,'{"seq":3,"concept":"SC6-1-u2-C1","difficulty":1,"kind":"ox","stem":"나무토막을 옮길 때는 뛰지 않고 걸어서 옮겨요.","answer":"O","reason_options":[{"t":"뛰다가 넘어져 다칠 수 있기 때문에","correct":true},{"t":"뛰면 나무토막이 무거워지기 때문에","mis":"SC6-1-u2-X01"}],"mis":"SC6-1-u2-X01","explanation":["걷는 놀이예요.","뛰면 넘어질 수 있어요.","맞는 말이에요."]}'::jsonb),
('g6_1_sci_u2_L01_basic#4','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C2',1,'sa','auto','「결승선을 가장 먼저 통과한 친구가 가장 □□□ 걸은 친구입니다.」 □□□에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC6-1-u2-C2","difficulty":1,"kind":"sa","stem":"「결승선을 가장 먼저 통과한 친구가 가장 □□□ 걸은 친구입니다.」 □□□에 알맞은 말을 쓰세요.","answer":["빠르게","빨리"],"explanation":["먼저 들어온 친구예요.","느리게의 반대예요.","빠르게예요."],"mis":"SC6-1-u2-X04"}'::jsonb),
('g6_1_sci_u2_L01_basic#5','sci',6,1,'u2','L01','g6_1_sci_u2_L01_basic','lesson_basic','SC6-1-u2-C1',2,'match','auto','걷는 방법과 나무토막을 두는 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC6-1-u2-C1","difficulty":2,"kind":"match","stem":"걷는 방법과 나무토막을 두는 자리를 알맞게 이으세요.","pairs":[{"l":"머리에 얹고 걷기","r":"정수리 위에 올리고 고개를 세워 걷는다"},{"l":"어깨에 얹고 걷기","r":"한쪽 어깨 위에 올리고 균형을 잡는다"},{"l":"무릎에 끼고 걷기","r":"두 무릎 사이에 끼워 종종걸음으로 간다"},{"l":"발등에 얹고 걷기","r":"발등 위에 올리고 한 걸음씩 옮긴다"}],"mis":"SC6-1-u2-X03","explanation":["나무토막이 있는 곳을 봐요.","몸의 자리가 달라요.","모습도 달라져요."],"asset":{"type":"passage","lines":["머리에 얹고 — 정수리 위에 올리고 고개를 세워 걸었다. 가장 먼저 통과했다.","어깨에 얹고 — 한쪽 어깨 위에 올리고 균형을 잡으며 걸었다.","무릎에 끼고 — 두 무릎 사이에 끼워 종종걸음으로 걸었다.","발등에 얹고 — 한 걸음씩 조심조심 옮겼다. 가장 나중에 통과했다.","네 친구 모두 같은 출발선에서 같은 결승선까지 걸었다."],"title":"나무토막 옮기기 결과"}}'::jsonb),
