('g6_1_sci_u2_L01_challenge#7','sci',6,1,'u2','L01','g6_1_sci_u2_L01_challenge','lesson_challenge','SC6-1-u2-C1',3,'mc','auto','활동할 때 알맞은 행동은 어느 것인가요?',ARRAY['SC6-1-u2-X01','SC6-1-u2-X02']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C1","difficulty":3,"kind":"mc","stem":"활동할 때 알맞은 행동은 어느 것인가요?","options":[{"t":"결승선을 통과한 뒤 나무토막을 손으로 잡아 내려놓는다","correct":true},{"t":"남은 나무토막을 친구에게 던지며 장난친다","mis":"SC6-1-u2-X01"},{"t":"더 빨리 가려고 결승선까지 뛰어간다","mis":"SC6-1-u2-X02"},{"t":"떨어진 나무토막을 그대로 두고 걸어간다","mis":"SC6-1-u2-X01"}],"explanation":["안전을 떠올려요.","던지거나 뛰지 않아요.","손으로 내려놓아요."]}'::jsonb),
