('g6_1_sci_u2_L02_basic#7','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C3',2,'ox','auto','과학에서 운동을 나타낼 때는 사람이나 동물도 물체에 포함돼요.',ARRAY['SC6-1-u2-X07']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C3","difficulty":2,"kind":"ox","stem":"과학에서 운동을 나타낼 때는 사람이나 동물도 물체에 포함돼요.","answer":"O","reason_options":[{"t":"사람이나 동물도 시간이 지남에 따라 위치가 변하면 운동하는 물체이기 때문에","correct":true},{"t":"물체는 사람이 만든 물건만을 뜻하기 때문에","mis":"SC6-1-u2-X07"}],"mis":"SC6-1-u2-X07","explanation":["걸어가는 친구를 떠올려요.","운동하는 물체였어요.","맞는 말이에요."]}'::jsonb),
('g6_1_sci_u2_L02_basic#8','sci',6,1,'u2','L02','g6_1_sci_u2_L02_basic','lesson_basic','SC6-1-u2-C5',2,'error','auto','사진 관찰을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X10']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C5","difficulty":2,"kind":"error","stem":"사진 관찰을 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「찍은 친구 사진을 누리망에 올려서 보여 주자.」","correct":true,"mis_target":"SC6-1-u2-X10"},{"t":"채윤 — 「관찰이 끝나면 찍은 사진을 삭제하자.」","mis":"SC6-1-u2-X10"},{"t":"도현 — 「창밖으로 손을 내밀지 말자.」","mis":"SC6-1-u2-X10"}],"explanation":["다른 사람을 찍은 사진이에요.","온라인에 올리지 않아요.","준서가 잘못 말했어요."]}'::jsonb),
