('g6_1_sci_u2_L02_challenge#2','sci',6,1,'u2','L02','g6_1_sci_u2_L02_challenge','lesson_challenge','SC6-1-u2-C5',2,'mc','auto','두 사진을 비교하는 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X08']::text[],false,'{"seq":2,"concept":"SC6-1-u2-C5","difficulty":2,"kind":"mc","stem":"두 사진을 비교하는 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"삼각대에 스마트 기기 고정 → 5초 간격으로 두 번 찍기 → 두 사진 비교 → 운동하는 물체 이야기하기","correct":true},{"t":"5초 간격으로 두 번 찍기 → 삼각대에 스마트 기기 고정 → 두 사진 비교 → 운동하는 물체 이야기하기","mis":"SC6-1-u2-X08"},{"t":"두 사진 비교 → 삼각대에 스마트 기기 고정 → 5초 간격으로 두 번 찍기 → 운동하는 물체 이야기하기","mis":"SC6-1-u2-X08"},{"t":"삼각대에 스마트 기기 고정 → 한 번만 찍기 → 운동하는 물체 이야기하기 → 두 사진 비교","mis":"SC6-1-u2-X08"}],"explanation":["먼저 기기를 고정해요.","두 번 찍고 비교해요.","마지막에 이야기해요."]}'::jsonb),
