('g6_1_sci_u2_L04_challenge#4','sci',6,1,'u2','L04','g6_1_sci_u2_L04_challenge','lesson_challenge','SC6-1-u2-C10',3,'error','auto','기록을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X17']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C10","difficulty":3,"kind":"error","stem":"기록을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「파란색이 5초 동안 덜 갔으니 파란색이 더 빨라.」","correct":true,"mis_target":"SC6-1-u2-X17"},{"t":"소이 — 「5초 동안 빨간색이 더 길게 갔어.」","mis":"SC6-1-u2-X17"},{"t":"유찬 — 「1초 뒤에도 빨간색이 더 멀리 있었어.」","mis":"SC6-1-u2-X17"}],"explanation":["같은 시간이에요.","길게 간 쪽이 빨라요.","하람이 잘못 말했어요."],"asset":{"type":"passage","lines":["같은 출발선에서 두 태엽 자동차를 동시에 출발시켰다.","1초 뒤 — 빨간색 27 cm · 파란색 24 cm","2초 뒤 — 빨간색 54 cm · 파란색 49 cm","3초 뒤 — 빨간색 81 cm · 파란색 73 cm","4초 뒤 — 빨간색 108 cm · 파란색 98 cm","5초 뒤 — 빨간색 135 cm · 파란색 122 cm"],"title":"5초 동안 이동한 거리(일의 자리까지)"}}'::jsonb),
