('g6_1_sci_u2_L05_basic#3','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C14',1,'sa','auto','노란색 자동차가 100 cm를 이동하는 데 걸린 시간은 몇 초인가요?','{}'::text[],false,'{"seq":3,"concept":"SC6-1-u2-C14","difficulty":1,"kind":"sa","stem":"노란색 자동차가 100 cm를 이동하는 데 걸린 시간은 몇 초인가요?","answer":["5.8","5.8초"],"explanation":["기록을 읽어요.","노란색 줄이에요.","5.8초예요."],"asset":{"type":"passage","lines":["결승선은 출발선에서 100 cm 떨어진 곳에 있다.","태엽 자동차를 한 대씩 출발시켜 걸린 시간을 쟀다.","초록색 자동차 — 4.2초","노란색 자동차 — 5.8초"],"title":"100 cm를 이동하는 데 걸린 시간(소수 첫째 자리까지)"},"mis":"SC6-1-u2-X22"}'::jsonb),
('g6_1_sci_u2_L05_basic#4','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C15',1,'ox','auto','같은 거리 실험에서는 태엽 자동차를 한 대씩 출발시켜 걸린 시간을 재요.',ARRAY['SC6-1-u2-X23']::text[],false,'{"seq":4,"concept":"SC6-1-u2-C15","difficulty":1,"kind":"ox","stem":"같은 거리 실험에서는 태엽 자동차를 한 대씩 출발시켜 걸린 시간을 재요.","answer":"O","reason_options":[{"t":"한 대씩 보내야 초시계로 걸린 시간을 정확하고 편하게 잴 수 있기 때문에","correct":true},{"t":"두 대를 함께 보내면 결승선이 멀어지기 때문에","mis":"SC6-1-u2-X23"}],"mis":"SC6-1-u2-X23","explanation":["초시계를 떠올려요.","한 대씩이 정확해요.","맞는 말이에요."]}'::jsonb),
('g6_1_sci_u2_L05_basic#5','sci',6,1,'u2','L05','g6_1_sci_u2_L05_basic','lesson_basic','SC6-1-u2-C14',2,'mc','auto','수영 경기에서 순위를 정하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC6-1-u2-X22','SC6-1-u2-X24','SC6-1-u2-X20']::text[],false,'{"seq":5,"concept":"SC6-1-u2-C14","difficulty":2,"kind":"mc","stem":"수영 경기에서 순위를 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"출발선에서 결승선까지 걸린 시간이 짧은 순서대로 정한다","correct":true},{"t":"걸린 시간이 긴 순서대로 정한다","mis":"SC6-1-u2-X22"},{"t":"출발하고 3초 뒤 앞서 있는 순서대로 정한다","mis":"SC6-1-u2-X24"},{"t":"키가 큰 순서대로 정한다","mis":"SC6-1-u2-X20"}],"explanation":["모두 같은 거리를 헤엄쳐요.","시간을 재요.","짧은 순서예요."]}'::jsonb),
