('g6_1_sci_u2_L06_basic#6','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C17',2,'match','auto','교통수단과 속력을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC6-1-u2-C17","difficulty":2,"kind":"match","stem":"교통수단과 속력을 알맞게 이으세요.","pairs":[{"l":"자전거로 1시간 동안 20 km","r":"20 km/h"},{"l":"자동차로 2시간 동안 145 km","r":"72.5 km/h"},{"l":"기차로 3시간 동안 450 km","r":"150 km/h"},{"l":"배로 4시간 동안 138 km","r":"34.5 km/h"}],"mis":"SC6-1-u2-X26","explanation":["거리를 시간으로 나눠요.","145 ÷ 2, 450 ÷ 3이에요.","단위를 붙여요."],"asset":{"type":"passage","lines":["자전거 — 1시간 동안 20 km","자동차 — 2시간 동안 145 km","기차 — 3시간 동안 450 km","배 — 4시간 동안 138 km","비행기 — 5시간 동안 4500 km"],"title":"교통수단이 이동한 거리와 걸린 시간"}}'::jsonb),
('g6_1_sci_u2_L06_basic#7','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C19',2,'error','auto','속력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC6-1-u2-X29']::text[],false,'{"seq":7,"concept":"SC6-1-u2-C19","difficulty":2,"kind":"error","stem":"속력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「10 km/h가 5 m/s보다 빨라. 10이 5보다 크잖아.」","correct":true,"mis_target":"SC6-1-u2-X29"},{"t":"하율 — 「30 km/h보다 50 km/h가 더 빨라.」","mis":"SC6-1-u2-X29"},{"t":"로운 — 「4 m/s보다 7 m/s가 더 빨라.」","mis":"SC6-1-u2-X29"}],"explanation":["단위를 먼저 봐요.","km/h와 m/s는 달라요.","지유가 잘못 말했어요."]}'::jsonb),
('g6_1_sci_u2_L06_basic#8','sci',6,1,'u2','L06','g6_1_sci_u2_L06_basic','lesson_basic','SC6-1-u2-C20',2,'ox','auto','빨간색 자동차의 속력 27.0 cm/s는 매 초 똑같이 27.0 cm씩 이동했다는 뜻이에요.',ARRAY['SC6-1-u2-X30']::text[],false,'{"seq":8,"concept":"SC6-1-u2-C20","difficulty":2,"kind":"ox","stem":"빨간색 자동차의 속력 27.0 cm/s는 매 초 똑같이 27.0 cm씩 이동했다는 뜻이에요.","answer":"X","reason_options":[{"t":"전체 이동 거리를 전체 걸린 시간으로 나누어 구한 값이기 때문에","correct":true},{"t":"속력은 언제나 매 초 똑같이 움직인 거리를 잰 것이기 때문에","mis":"SC6-1-u2-X30"}],"mis":"SC6-1-u2-X30","explanation":["기록을 떠올려요.","1초 뒤 27 cm, 2초 뒤 54 cm처럼 재지 않았어요.","전체로 구한 값이에요."]}'::jsonb),
